// Cyclic Noise Bicolore (Ray Marching)
// Variante a DUE COLORI di "Noise": stesso cuore di cyclic noise 3D, ma il
// rumore pilota UN SOLO scalare di mix tra u_col2 e u_col1. Cosi' i picker
// Colore Texture del dock (col1/col2) controllano davvero il risultato, a
// differenza della versione a palette che genera uno spettro continuo.
//
// Variabili dell'engine disponibili in questo blocco (tab Ray Marching):
//   pModel       = punto di hit sulla superficie (vec3, model space)
//   n_model      = normale alla superficie nel punto di hit (vec3)
//   textureCol   = colore da assegnare (gia' inizializzato a ubuf.color)
//   ubuf.u_time  = tempo animato; ubuf.u_col1 / ubuf.u_col2 = colori del dock
// NB: niente mainImage, niente return, niente gl_FragCoord in questo tab.

// --- Cyclic noise 3D: loop iterato di |dot(cos,sin)| con distorsione e rotazione ---
float result = 0.0;
float z = 0.95;
float distort = 2.1;
float dstAmount = 0.10;
float wsum = 0.0;

mat3 m2 = mat3(
    0.97367,  0.22798, 0.0,
   -0.22798,  0.97367, 0.0,
    0.0,      0.0,     1.0) * 1.5;

vec3 p = pModel * 2.3 + vec3(0.0, 0.0, ubuf.u_time * 0.05);

for (int i = 0; i < 8; i++) {
    p += sin(p.yzx * distort + ubuf.u_time * 0.27 * pow(distort, 1.35)) * dstAmount;
    result += abs(dot(cos(p), sin(p.zxy)) * z);
    wsum   += z;
    z       *= 0.65;
    distort *= 1.35;
    p        = m2 * p;
}
float ncyc = clamp(result / wsum, 0.0, 1.0);   // ~[0,1]

// curva di contrasto morbida per separare bene i due colori
float tcol = smoothstep(0.25, 0.75, ncyc);

// SOLO i due colori del dock: interpolazione di un singolo scalare
vec3 bicolor = mix(ubuf.u_col2, ubuf.u_col1, tcol);

// sheen di bordo NEUTRO (grigio): schiarisce le creste senza introdurre
// tinte estranee ai due colori scelti
float fres = pow(1.0 - abs(n_model.z), 2.0);
bicolor += vec3(fres * 0.12 * ncyc);

textureCol = bicolor;
